  for (const user of users) {
    if (user.id === targetId) {
      return user;
    }
  }
  return undefined;
}

function processUsers(users: User[], targetIds: string[]) {
  const results: User[] = [];
  for (const id of targetIds) {
    const user = findUser(users, id);
    if (user) {
      results.push(user);
    }
  }
